867	  let idx = 0;
868	
869	  while (idx < linearRules.length) {
870	    const ruleDef = linearRules[idx];
871	    if (isRuleDefChar(ruleDef) || isRuleDefCharNot(ruleDef)) {
872	      // this could be a single char, or a range, or a sequence of alts; we don't know until we step through it.
873	      const charRule = makeCharRule(ruleDef);
874	      idx += 1;
875	      let rule: InternalRuleDef | null = idx < linearRules.length ? linearRules[idx] : null;
876	      while (idx < linearRules.length && (isRuleDefCharRngUpper(rule) || isRuleDefCharAlt(rule))) {
877	        if (isRuleDefCharRngUpper(rule)) {
878	          // previous rule value should be a number
879	          const prevValue = charRule.value.pop();
880	          if (isRange(prevValue)) {
