964	/** Returns the parsed code point and the number of characters it consumed. */
965	export const parseChar = (src: string, pos: number): [number, number] => {
966	  if (pos >= src.length) {
967	    throw new GrammarParseError(
968	      src,
969	      pos,
970	      'Unexpected end of grammar input, failed to complete parse',
971	    );
972	  }
973	
974	  if (src[pos] === '\\') {
975	    const next = src[pos + 1];
976	    if (next === 'x') {
977	      return [parseHex(src, pos + 2, pos + 4), 4];
978	    }
979	    if (next === 'u') {
980	      return [parseHex(src, pos + 2, pos + 6), 6];
981	    }
982	    if (next === 'U') {
983	      return [parseHex(src, pos + 2, pos + 10), 10];
984	    }
985	    if (next in SIMPLE_ESCAPES) {
986	      return [SIMPLE_ESCAPES[next].codePointAt(0) as number, 2];
987	    }
988	    if (LITERAL_ESCAPES.includes(next)) {
989	      return [next.codePointAt(0) as number, 2];
990	    }
991	    throw new GrammarParseError(src, pos, `Unknown escape at ${src[pos]}`);
992	  }
993	
994	  // Python indexes strings by code point; JS by UTF-16 unit, so an astral
995	  // character occupies two positions here and has to advance `pos` by two.
996	  const codePoint = src.codePointAt(pos) as number;
997	  return [codePoint, codePoint > 0xffff ? 2 : 1];
