import ast, pathlib
for p in sorted(pathlib.Path('gbnf').rglob('*.py')):
    src = p.read_text(); tree = ast.parse(src)
    names = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Name): names.add(n.id)
        elif isinstance(n, ast.Attribute): pass
    text_ids = {t.id for t in ast.walk(tree) if isinstance(t, ast.Name)}
    attr_roots = {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
    strings = {s.value for s in ast.walk(tree) if isinstance(s, ast.Constant) and isinstance(s.value, str)}
    used = text_ids | attr_roots | strings
    unused = []
    for n in ast.walk(tree):
        if isinstance(n, (ast.Import, ast.ImportFrom)):
            for a in n.names:
                nm = (a.asname or a.name).split('.')[0]
                if nm not in used and nm != '*': unused.append(nm)
    if unused: print(p, '->', unused)
EOF
